it('Should merge cookies set on c.res with cookies from a new Response', () => {
  const middlewareCookie = 'middleware=1; Path=/'
  const handlerCookie = 'handler=1; Path=/'
  c.res.headers.append('set-cookie', middlewareCookie)

  c.res = new Response('ok', {
    headers: { 'set-cookie': handlerCookie },
  })

  const cookies = c.res.headers.getSetCookie()
  expect(cookies).toHaveLength(2)
  expect(cookies).toContain(middlewareCookie)
  expect(cookies).toContain(handlerCookie)
})

